import { WORKING_HOURS } from '../constants';

export const getCurrentStatus = () => {
  const now = new Date();
  const day = now.getDay();
  const hours = now.getHours();
  const minutes = now.getMinutes();
  const currentTime = hours * 60 + minutes;

  const schedule = WORKING_HOURS[day];

  if (schedule.isClosed) return false;

  const [openH, openM] = schedule.open.split(':').map(Number);
  const [closeH, closeM] = schedule.close.split(':').map(Number);

  const openTime = openH * 60 + openM;
  const closeTime = closeH * 60 + closeM;

  return currentTime >= openTime && currentTime <= closeTime;
};

export const getStatusLabel = (isOpen: boolean) => isOpen ? "مفتوح الآن" : "مغلق الآن";

import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { getCurrentStatus, getStatusLabel } from '../utils/status';

const StatusIndicator: React.FC = () => {
  const [isOpen, setIsOpen] = useState(getCurrentStatus());

  useEffect(() => {
    const timer = setInterval(() => {
      setIsOpen(getCurrentStatus());
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div className="flex items-center gap-2 px-3 py-1 rounded-full border border-slate-200 bg-white shadow-sm">
      <motion.div 
        animate={{ opacity: [1, 0.4, 1] }}
        transition={{ repeat: Infinity, duration: 2 }}
        className={`w-2.5 h-2.5 rounded-full ${isOpen ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.6)]' : 'bg-rose-500'}`} 
      />
      <span className={`text-xs font-bold ${isOpen ? 'text-emerald-700' : 'text-rose-700'}`}>
        {getStatusLabel(isOpen)}
      </span>
    </div>
  );
};

export default StatusIndicator;

